import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource@12983fa53d4da19dc1f2a5e6b8c37a0eb12f2aa5/dist/util/mvu_zod.js';

// 首版 MVU 状态。规范：docs/协议与状态.md 第 3 节。
// 运行时使用酒馆助手注入的全局 z（zod 4.4.3）；测试时由测试文件注入同版本 zod。

const count = (fallback        , min = 0) =>
  z.coerce
    .number()
    .transform(v => Math.max(min, Math.trunc(Number.isFinite(v) ? v : fallback)))
    .prefault(fallback);

export const Schema = z.object({
  日程: z
    .object({
      日期: z.string().regex(/^\d{4}-\d{2}-\d{2}$/).prefault('2016-04-09'),
      时间段: z.enum(['清晨', '上午', '午休', '下午', '放学后', '白天', '夜晚']).prefault('白天'),
    })
    .prefault({}),
  地点: z
    .object({
      世界: z.enum(['现实', '认知世界']).prefault('现实'),
      区域: z.string().prefault('四轩茶屋'),
      场所: z.string().prefault('卢布朗'),
    })
    .prefault({}),
  剧情: z
    .object({
      章节: z.enum(['序章', '鸭志田宫殿']).prefault('序章'),
      已完成事件: z.array(z.string()).prefault([]),
    })
    .prefault({}),
  Joker: z
    .object({
      等级: count(1, 1),
      经验: count(0),
      HP: count(100),
      HP上限: count(100, 1),
      SP: count(50),
      SP上限: count(50, 1),
      Persona: z.array(z.string()).prefault([]),
      当前Persona: z.string().prefault(''),
    })
    .transform(j => ({ ...j, HP: Math.min(j.HP, j.HP上限), SP: Math.min(j.SP, j.SP上限) }))
    .prefault({}),
});



/** 只有前端可以写的顶层字段。 */
export const FRONTEND_OWNED = ['日程', '剧情', 'Joker']         ;

$(() => {
  registerMvuSchema(Schema);
});

// 心之怪盗团 · 入口（D-14 远程加载）：主程序和图片不在卡里，按顺序尝试下面的来源。
(async () => {
  const sources = [`https://cdn.jsdelivr.net/gh/cy4268/p5r-phantom-thieves-release@0.1.0/p5r.js`, `https://testingcf.jsdelivr.net/gh/cy4268/p5r-phantom-thieves-release@0.1.0/p5r.js`];
  for (const url of sources) {
    try {
      await import(url);
      return;
    } catch (error) {
      console.warn('[P5R] 来源加载失败：', url, error);
    }
  }
  toastr.error('心之怪盗团的主程序加载失败：所有来源都连不上。请检查网络后刷新页面。', '', { timeOut: 0 });
})();
